// Function to perform Breadth-First Search (BFS) on a graph
function bfs(graph: number[][], start: number): number[] {
  // Initialize a set to keep track of visited nodes
  const visited = new Set<number>();

  // Initialize a queue for BFS traversal, starting with the given start node
  const queue: number[] = [start];

  // Initialize an array to store the BFS traversal result
  const result: number[] = [];

  // Mark the starting node as visited
  visited.add(start);

  // Continue the traversal as long as the queue is not empty
  while (queue.length > 0) {
    // Dequeue a node from the front of the queue
    const node = queue.shift()!;

    // Add the dequeued node to the result array
    result.push(node);

    // Iterate through the neighbors of the current node
    for (const neighbor of graph[node]) {
      // If the neighbor has not been visited
      if (!visited.has(neighbor)) {
        // Mark the neighbor as visited
        visited.add(neighbor);

        // Enqueue the neighbor to the back of the queue
        queue.push(neighbor);
      }
    }
  }

  // Return the BFS traversal result
  return result;
}

/**
 * Performs a Breadth-First Search (BFS) traversal on a given graph.
 *
 * @param graph A 2D array representing the adjacency list of the graph.
 *              graph[i] contains a list of neighbors of node i.
 * @param start The starting node for the BFS traversal.
 * @return A list of nodes visited in BFS order, starting from the start node.
 */

  public static List<Integer> bfs(List<List<Integer>> graph, int start) {
    // Use a Set to keep track of visited nodes to avoid cycles.
    Set<Integer> visited = new HashSet<>();

    // Use a Queue to maintain the order of nodes to visit (FIFO).
    Queue<Integer> queue = new LinkedList<>();

    // Store the result, i.e., the nodes visited in BFS order.
    List<Integer> result = new ArrayList<>();

    // Mark the starting node as visited and enqueue it.
    visited.add(start);
    queue.offer(start);

    // While the queue is not empty, continue the traversal.
    while (!queue.isEmpty()) {
      // Dequeue a node from the queue.
      int node = queue.poll();

      // Add the dequeued node to the result list.
      result.add(node);

      // Iterate through the neighbors of the current node.
      for (int neighbor : graph.get(node)) {
        // If the neighbor has not been visited,
        if (!visited.contains(neighbor)) {
          // Mark it as visited and enqueue it.
          visited.add(neighbor);
          queue.offer(neighbor);
        }
      }
    }

    // Return the list of nodes visited in BFS order.
    return result;
  }

class Solution {
public:
  vector < int > bfs(vector<vector<int>> & graph, int start) {
  // Initialize an unordered set to keep track of visited nodes.
  unordered_set < int > visited;
  // Initialize a queue for BFS traversal.
  queue < int > q;
  // Initialize a vector to store the result (BFS traversal order).
  vector < int > result;

  // Mark the starting node as visited and enqueue it.
  visited.insert(start);
  q.push(start);

  // Perform BFS until the queue is empty.
  while (!q.empty()) {
    // Dequeue a node from the front of the queue.
    int node = q.front();
    q.pop();
    // Add the dequeued node to the result vector.
    result.push_back(node);

    // Iterate through the neighbors of the current node.
    for (int neighbor : graph[node]) {
           // If the neighbor has not been visited yet...
      if (visited.find(neighbor) == visited.end()) {
        // Mark the neighbor as visited.
        visited.insert(neighbor);
        // Enqueue the neighbor for further exploration.
        q.push(neighbor);
      }
    }
  }

  // Return the BFS traversal result.
  return result;
}
};

// Function to count the number of connected components in an undirected graph.
function countComponents(n: number, edges: number[][]): number {
  // Initialize the parent array, where parent[i] is the parent of node i.
  // Initially, each node is its own parent, representing individual components.
  const parent: number[] = Array.from({ length: n }, (_, i) => i);

  // Initialize the rank array, which is used to optimize the union operation.
  // Initially, each node has a rank of 1.
  const rank: number[] = new Array(n).fill(1);

  // Find the root/representative of the set to which the node belongs.
  function find(node: number): number {
    let res = node;

    // Traverse up the parent pointers until we find the root (parent[res] === res).
    while (res !== parent[res]) {
      // Path compression: update the parent of the current node to be the grandparent,
      // effectively flattening the tree structure for faster future finds.
      parent[res] = parent[parent[res]];
      res = parent[res];
    }

    return res;
  }

  // Unite the sets containing nodes n1 and n2.
  function union(n1: number, n2: number): number {
    const p1 = find(n1);
    const p2 = find(n2);

    // If n1 and n2 are already in the same set, do nothing and return 0.
    if (p1 === p2) {
      return 0;
    }

    // Union by rank: attach the tree with smaller rank to the tree with larger rank.
    // This helps to keep the tree structure relatively flat, optimizing find operations.
    if (rank[p2] > rank[p1]) {
      parent[p1] = p2;
      rank[p2] += rank[p1];
    } else {
      parent[p2] = p1;
      rank[p1] += rank[p2];
    }

    return 1; // Return 1 to indicate a successful union.
  }

  // Initially, the number of connected components is equal to the number of nodes.
  let result = n;

  // Iterate through the edges and perform the union operation for each edge.
  for (const [n1, n2] of edges) {
    result -= union(n1, n2);
  }

  // Return the final number of connected components.
  return result;
}

public static class Solution {

public int countComponents(int n, int[][] edges) {
    // Initialize the parent array. Each node is its own parent initially.
    int[] parent = new int[n];
    // Initialize the rank array. Rank is used to optimize the union operation.
    int[] rank = new int[n];

    // Initially, each node is its own root, and the rank is 1.
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 1;
    }

    // Initially, the number of components is the number of nodes.
    int result = n;

    // Iterate through each edge and perform the union operation.
    for (int[] edge : edges) {
        // The union operation returns 1 if a union was performed (i.e., the nodes were in different components).
        // We decrement the result (number of components) if a union was performed.
        result -= union(edge[0], edge[1], parent, rank);
    }

    // Return the final number of connected components.
    return result;
}

// The find operation with path compression.
private int find(int node, int[] parent) {
    int res = node;

    // Find the root of the node.
    while (res != parent[res]) {
        // Path compression: make the node's parent the grandparent.
        parent[res] = parent[parent[res]]; 
        res = parent[res];
    }

    // Return the root of the node.
    return res;
}

// The union operation with rank optimization.
private int union(int n1, int n2, int[] parent, int[] rank) {
    // Find the roots of the two nodes.
    int p1 = find(n1, parent);
    int p2 = find(n2, parent);

    // If the roots are the same, the nodes are already in the same component, so return 0 (no union performed).
    if (p1 == p2) {
        return 0;
    }

    // Union by rank: attach the smaller rank tree to the larger rank tree.
    if (rank[p2] > rank[p1]) {
        parent[p1] = p2;
        rank[p2] += rank[p1];
    } else {
        parent[p2] = p1;
        rank[p1] += rank[p2];
    }

    // Return 1 to indicate that a union was performed.
    return 1;
}

}

class Solution {
public:
int countComponents(int n, vector<vector<int>>& edges) {

    // Initialize parent array where each node is its own parent initially.
    vector<int> parent(n);
    // Initialize rank array to 1 for each node.  Rank is used to optimize union operation (union by rank).
    vector<int> rank(n, 1);

    // Initially, each node is its own component.
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    // Initially, the number of components equals the number of nodes.
    int result = n;

    // Iterate through the edges and perform the union operation.
    for (auto &edge : edges) {
        // Unite the two nodes connected by the edge. If they were already in the same component,
        // unite function returns 0, otherwise, it unites them and returns 1.
        // Subtract the returned value from the result, effectively reducing the component count.
        result -= unite(edge[0], edge[1], parent, rank);
    }

    // Return the final number of connected components.
    return result;
}


private:

// Find the root/representative of the set/component that the node belongs to.
int find(int node, vector<int>& parent) {
    int res = node;

    // Traverse to find the root.  The root is the node whose parent is itself.
    while (res != parent[res]) {
        // Path compression:  Update the parent of the current node to be the grandparent.
        // This flattens the tree structure and makes future find operations faster.
        parent[res] = parent[parent[res]]; // path compression
        res = parent[res];
    }

    // Return the root of the component.
    return res;
}

// Unite two components containing nodes n1 and n2, respectively.
int unite(int n1, int n2, vector<int>& parent, vector<int>& rank) {

    // Find the roots of the components that n1 and n2 belong to.
    int p1 = find(n1, parent);
    int p2 = find(n2, parent);

    // If n1 and n2 are already in the same component (i.e., have the same root),
    // then there's nothing to do. Return 0 to indicate no change in component count.
    if (p1 == p2) {
        return 0;
    }

    // Union by rank: Attach the smaller rank tree under the root of the higher rank tree.
    // This helps to keep the tree relatively flat, thus optimizing find operations.
    if (rank[p2] > rank[p1]) {
        parent[p1] = p2;
        rank[p2] += rank[p1];
    } else {
        parent[p2] = p1;
        rank[p1] += rank[p2];
    }

    // Return 1 to indicate that two components have been merged.
    return 1;
}

};

function minCostConnectPoints(points: number[][]): number {
    const n = points.length; // Get the number of points.

    // Helper function to calculate Manhattan distance between two points.
    function manhattanDistance(p1: number[], p2: number[]): number {
        return Math.abs(p1[0] - p2[0]) + Math.abs(p1[1] - p2[1]); // Calculate Manhattan distance: |x1 - x2| + |y1 - y2|.
    }

    // Build the edges array: [u, v, weight], where u and v are point indices and weight is the Manhattan distance.
    const edges: number[][] = [];
    for (let i = 0; i < n; i++) { // Iterate through each point.
        for (let j = i + 1; j < n; j++) { // Iterate through the remaining points to avoid duplicates.
            edges.push([i, j, manhattanDistance(points[i], points[j])]); // Create an edge with the two point indices and their Manhattan distance.
        }
    }

    // Sort edges by weight in ascending order. This is crucial for Kruskal's algorithm.
    edges.sort((a, b) => a[2] - b[2]); // Sort based on the weight (Manhattan distance) which is the third element of each edge.

    // Initialize disjoint set (Union-Find) data structure.
    const parent: number[] = Array(n).fill(0).map((_, i) => i); // Each point initially is its own parent.

    // Find operation with path compression.  Finds the root/representative of the set to which element i belongs.
    function find(i: number): number {
        if (parent[i] === i) { // If the parent of i is i itself, then i is the root of its set.
            return i; // Return the root.
        }
        return parent[i] = find(parent[i]); // Path compression: set the parent of i to the root of its set directly.
    }

    // Union operation.  Merges the sets containing elements i and j.
    function union(i: number, j: number): void {
        const rootI = find(i); // Find the root of the set containing i.
        const rootJ = find(j); // Find the root of the set containing j.
        if (rootI !== rootJ) { // If i and j are in different sets.
            parent[rootI] = rootJ; // Make the root of i's set point to the root of j's set, merging the two sets.
        }
    }

    let mstCost = 0; // Initialize the total cost of the MST.
    let edgesUsed = 0; // Initialize the count of edges added to the MST.

    // Kruskal's algorithm: Iterate through the sorted edges and add edges to the MST if they don't form a cycle.
    for (const edge of edges) {
        const u = edge[0]; // Get the first point index of the edge.
        const v = edge[1]; // Get the second point index of the edge.
        const weight = edge[2]; // Get the weight (Manhattan distance) of the edge.

        if (find(u) !== find(v)) { // Check if adding the edge creates a cycle. If the roots are different, it doesn't create a cycle.
            union(u, v); // Merge the sets containing u and v.
            mstCost += weight; // Add the weight of the edge to the MST cost.
            edgesUsed++; // Increment the count of edges used.
            if (edgesUsed === n - 1) { // If we have added n-1 edges, we have connected all points, so we can stop.
                break; // Exit the loop.
            }
        }
    }

    return mstCost; // Return the total cost of the minimum spanning tree.
}

public static class Solution {

    public int minCostConnectPoints(int[][] points) {

        int N = points.length;

        // adjacency list: node -> {cost, neighbor}
        Map<Integer, List<int[]>> adj = new HashMap<>();

        // Initialize the adjacency list for each point
        for (int i = 0; i < N; i++) {
            adj.put(i, new ArrayList<>());
        }

        // Build graph using Manhattan distance
        for (int i = 0; i < N; i++) {

            int x1 = points[i][0];
            int y1 = points[i][1];

            // Iterate through all other points to create edges
            for (int j = i + 1; j < N; j++) {

                int x2 = points[j][0];
                int y2 = points[j][1];

                // Calculate Manhattan distance between points i and j
                int dist = Math.abs(x1 - x2) + Math.abs(y1 - y2);

                // Add edge to adjacency list for both points i and j
                adj.get(i).add(new int[]{dist, j});
                adj.get(j).add(new int[]{dist, i});
            }
        }

        int result = 0;

        // Keep track of visited nodes
        Set<Integer> visit = new HashSet<>();

        // Min heap [cost, node]
        // PriorityQueue to store edges with their costs, sorted by cost
        PriorityQueue<int[]> minHeap =
                new PriorityQueue<>((a, b) -> a[0] - b[0]);

        // Start from node 0 with cost 0
        minHeap.offer(new int[]{0, 0});

        // While not all nodes are visited
        while (visit.size() < N) {

            // Get the edge with the minimum cost from the heap
            int[] top = minHeap.poll();
            int cost = top[0];
            int node = top[1];

            // If node is already visited, skip it
            if (visit.contains(node)) continue;

            // Add the cost to the result
            result += cost;
            // Mark the node as visited
            visit.add(node);

            // Iterate through all neighbors of the current node
            for (int[] edge : adj.get(node)) {

                int neiCost = edge[0];
                int nei = edge[1];

                // If the neighbor is not visited, add it to the heap
                if (!visit.contains(nei)) {
                    minHeap.offer(new int[]{neiCost, nei});
                }
            }
        }

        return result;
    }
}

