public static class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        // Build the adjacency list (graph) to represent the network.
        Map<Integer, List<int[]>> edges = new HashMap<>();
        for (int[] time : times) {
            int u = time[0]; // Source node
            int v = time[1]; // Target node
            int w = time[2]; // Weight (travel time)
            edges.computeIfAbsent(u, key -> new ArrayList<>()).add(new int[]{v, w});
        }

        // Priority queue (min-heap) to store nodes to visit, prioritized by their distance from the source.
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0])); // [distance, node]
        minHeap.offer(new int[]{0, k}); // Start at node k with a distance of 0.

        Set<Integer> visit = new HashSet<>(); // Keep track of visited nodes.
        int t = 0; // Variable to store the maximum time taken to reach all nodes.

        while (!minHeap.isEmpty()) {
            int[] current = minHeap.poll(); // Get the node with the smallest distance.
            int w1 = current[0]; // Distance to the current node
            int n1 = current[1]; // Current node

            if (visit.contains(n1)) continue; // If already visited, skip.

            visit.add(n1); // Mark the current node as visited.
            t = Math.max(t, w1); // Update the maximum time.

            List<int[]> neighbors = edges.getOrDefault(n1, new ArrayList<>()); // Get neighbors of current node.

            for (int[] neighbor : neighbors) {
                int n2 = neighbor[0]; // Neighbor node
                int w2 = neighbor[1]; // Weight of the edge to the neighbor
                if (!visit.contains(n2)) {
                    minHeap.offer(new int[]{w1 + w2, n2}); // Add neighbor to the priority queue with updated distance.
                }
            }
        }

        // If all nodes have been visited, return the maximum time. Otherwise, return -1.
        return visit.size() == n ? t : -1;
    }
}

class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {

        // Build adjacency list representing the graph.
        // The keys are the source nodes, and the values are vectors of pairs.
        // Each pair represents a destination node and the weight of the edge.
        unordered_map<int, vector<pair<int,int>>> edges;

        // Iterate through the 'times' vector to populate the adjacency list.
        for (auto &time : times) {
            int u = time[0]; // Source node.
            int v = time[1]; // Destination node.
            int w = time[2]; // Weight of the edge from u to v.
            edges[u].push_back({v, w}); // Add the edge to the adjacency list.
        }

        // Min heap (priority queue) to store nodes to visit, prioritized by distance.
        // The pair stores {distance, node}.
        // 'greater<pair<int,int>>' makes it a min-heap.
        priority_queue<
            pair<int,int>,
            vector<pair<int,int>>,
            greater<pair<int,int>>
        > minHeap;

        // Add the starting node 'k' to the min-heap with a distance of 0.
        minHeap.push({0, k});

        // 'visit' set to keep track of visited nodes.
        set<int> visit;

        // 't' to store the maximum time taken to reach all nodes.
        int t = 0;

        // Dijkstra's algorithm.
        while (!minHeap.empty()) {

            // Get the node with the smallest distance from the min-heap.
            auto [w1, n1] = minHeap.top(); // w1: distance, n1: node.
            minHeap.pop();

            // If the node has already been visited, skip it.
            if (visit.count(n1)) continue;

            // Mark the current node as visited.
            visit.insert(n1);

            // Update the maximum time taken so far.
            t = max(t, w1);

            // Iterate through the neighbors of the current node.
            for (auto &[n2, w2] : edges[n1]) { // n2: neighbor, w2: weight of edge from n1 to n2.
                // If the neighbor has not been visited, add it to the min-heap.
                if (!visit.count(n2)) {
                    minHeap.push({w1 + w2, n2}); // Distance to neighbor is the distance to current node + edge weight.
                }
            }
        }

        // If all nodes have been visited, return the maximum time taken. Otherwise, return -1.
        return visit.size() == n ? t : -1;
    }
