function networkDelayTime(times: number[][], n: number, k: number): number {
    const edges: Map<number, [number, number][]> = new Map();

    // Build adjacency list:  node -> [(neighbor, weight)]
    for (const [u, v, w] of times) {
        if (!edges.has(u)) {
            edges.set(u, []);
        }
        edges.get(u)!.push([v, w]);
    }

    // Min heap: [time, node].  Simulated with array and sorting.
    const minHeap: [number, number][] = [[0, k]]; // Start at node k with time 0

    const visit = new Set<number>(); // Keep track of visited nodes
    let t = 0; // Maximum time it takes to reach all nodes

    while (minHeap.length > 0) {
        // Get node with smallest time from the minHeap
        minHeap.sort((a, b) => a[0] - b[0]); // Sort by time
        const [w1, n1] = minHeap.shift()!;

        // If already visited, skip
        if (visit.has(n1)) continue;

        // Mark as visited
        visit.add(n1);
        t = Math.max(t, w1); // Update the maximum time

        // Explore neighbors
        const neighbors = edges.get(n1) || [];

        for (const [n2, w2] of neighbors) {
            // If neighbor not visited, add to minHeap with updated time
            if (!visit.has(n2)) {
                minHeap.push([w1 + w2, n2]);
            }
        }
    }

    // If all nodes visited, return the maximum time, otherwise return -1
    return visit.size === n ? t : -1;
}

function findCheapestPrice(
  n: number,
  flights: number[][],
  src: number,
  dst: number,
  k: number
): number {
  // Initialize an array to store the minimum prices to reach each city from the source.
  const prices: number[] = new Array(n).fill(Infinity);
  // The price to reach the source city itself is 0.
  prices[src] = 0;

  // Iterate k+1 times, where k is the maximum number of stops allowed. Each iteration represents one more stop.
  for (let i = 0; i <= k; i++) {
    // Create a temporary array to store the updated prices for the current iteration.
    // This ensures that updates are based on the previous iteration's prices.
    const tmpPrices = [...prices];

    // Iterate through each flight to find potentially cheaper paths.
    for (const [s, d, p] of flights) {
      // If the source city 's' is unreachable (price is Infinity), skip this flight.
      if (prices[s] === Infinity) continue;

      // If going from 's' to 'd' via this flight 'p' is cheaper than the current cheapest price to 'd',
      // update the temporary price for city 'd'.
      if (prices[s] + p < tmpPrices[d]) {
        tmpPrices[d] = prices[s] + p;
      }
    }

    // After iterating through all flights, update the 'prices' array with the 'tmpPrices' for the next iteration.
    for (let j = 0; j < n; j++) {
      prices[j] = tmpPrices[j];
    }
  }

  // After k+1 iterations, check if the destination city 'dst' is reachable.
  // If prices[dst] is still Infinity, it means there's no path within k stops, so return -1.
  // Otherwise, return the cheapest price to reach the destination.
  return prices[dst] === Infinity ? -1 : prices[dst];
}

public static class Solution {
    /**
     * Finds the cheapest price from src to dst with at most k stops using Bellman-Ford algorithm.
     *
     * @param n       The number of cities.
     * @param flights The list of flights, where flights[i] = [fromi, toi, pricei].
     * @param src     The source city.
     * @param dst     The destination city.
     * @param k       The maximum number of stops allowed.
     * @return The cheapest price from src to dst with at most k stops, or -1 if no such route exists.
     */
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        // Initialize an array to store the minimum prices to each city from the source.
        // Initially, set all prices to infinity except for the source city, which is 0.
        int[] prices = new int[n];
        Arrays.fill(prices, Integer.MAX_VALUE);
        prices[src] = 0;

        // Iterate k+1 times, where k is the maximum number of stops allowed.
        // Each iteration relaxes the edges, updating the minimum prices.
        for (int i = 0; i <= k; i++) {
            // Create a temporary array to store the prices for this iteration.
            // This prevents updates from affecting other calculations within the same iteration.
            int[] tmpPrices = Arrays.copyOf(prices, n);

            // Iterate through each flight in the flights array.
            for (int[] flight : flights) {
                int s = flight[0]; // Source city of the flight.
                int d = flight[1]; // Destination city of the flight.
                int p = flight[2]; // Price of the flight.

                // If the price to reach the source city 's' is still infinity,
                // it means it's not reachable, so we skip this flight.
                if (prices[s] == Integer.MAX_VALUE) continue;

                // If the price to reach the destination city 'd' through city 's'
                // is cheaper than the current minimum price to reach 'd',
                // update the temporary prices array.
                if (prices[s] + p < tmpPrices[d]) {
                    tmpPrices[d] = prices[s] + p;
                }
            }

            // Update the prices array with the values from the temporary array.
            // This ensures that the prices are updated after each iteration.
            prices = Arrays.copyOf(tmpPrices, n);
        }

        // After k+1 iterations, the prices array contains the minimum prices to each city
        // with at most k stops. If the price to reach the destination city 'dst' is still infinity,
        // it means it's not reachable within k stops, so we return -1.
        // Otherwise, we return the minimum price to reach 'dst'.
        return prices[dst] == Integer.MAX_VALUE ? -1 : prices[dst];
    }
}

