function floydWarshall(n: number, edges: [number, number, number][]): number[][] {
  // Initialize the distance matrix with Infinity for all pairs of vertices.
  const dist = Array.from({ length: n }, () => Array(n).fill(Infinity));

  // Set the distance from a vertex to itself to 0.
  for (let i = 0; i < n; i++) dist[i][i] = 0;

  // Populate the distance matrix with the direct edge weights from the input edges.
  // If there's no direct edge, the distance remains Infinity.
  for (const [u, v, w] of edges) {
    // Update the distance between u and v with the weight w, taking the minimum in case of duplicate edges.
    dist[u][v] = Math.min(dist[u][v], w);
  }

  // Floyd-Warshall algorithm: Iterate through all possible intermediate vertices k.
  for (let k = 0; k < n; k++) {
    // Iterate through all possible starting vertices i.
    for (let i = 0; i < n; i++) {
      // Iterate through all possible ending vertices j.
      for (let j = 0; j < n; j++) {
        // Check if going from i to j through k is shorter than the current distance from i to j.
        dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }

  // Return the final distance matrix containing the shortest path distances between all pairs of vertices.
  return dist;
}

public static  class Solution {
    public int[][] floydWarshall(int n, int[][] edges) {
        int[][] dist = new int[n][n];

        // Initialize distances between all pairs of nodes.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // If i == j, the distance is 0 (distance to itself).
                // Otherwise, initialize to a large value (representing infinity) to indicate no path.
                // Integer.MAX_VALUE / 2 is used to prevent integer overflow during calculations.
                dist[i][j] = (i == j) ? 0 : Integer.MAX_VALUE / 2; // Avoid overflow
            }
        }

        // Populate the distance matrix with the direct edge weights from the input.
        for (int[] edge : edges) {
            int u = edge[0]; // Source node of the edge.
            int v = edge[1]; // Destination node of the edge.
            int w = edge[2]; // Weight of the edge.
            dist[u][v] = w; // Set the distance from u to v to the weight w.
        }

        // Floyd-Warshall algorithm: Find the shortest path between all pairs of nodes.
        // Iterate through all possible intermediate nodes 'k'.
        for (int k = 0; k < n; k++) {
            // Iterate through all possible source nodes 'i'.
            for (int i = 0; i < n; i++) {
                // Iterate through all possible destination nodes 'j'.
                for (int j = 0; j < n; j++) {
                    // Check if going from 'i' to 'j' through 'k' is shorter than the current distance.
                    // dist[i][j] is the current shortest distance from 'i' to 'j'.
                    // dist[i][k] + dist[k][j] is the distance from 'i' to 'j' through 'k'.
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }

        // Return the resulting distance matrix, which contains the shortest path distances between all pairs of nodes.
        return dist;
    }
}

class Solution {
public:
    vector<vector<int>> floydWarshall(int n, vector<vector<int>>& edges) {

        const int INF = INT_MAX / 2; // Initialize infinity as a large value to avoid potential overflow during addition.
        vector<vector<int>> dist(n, vector<int>(n)); // Initialize the distance matrix with dimensions n x n.

        // Initialize distances
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) dist[i][j] = 0; // The distance from a node to itself is 0.
                else dist[i][j] = INF; // Initialize all other distances to infinity, indicating no direct path.
            }
        }

        // Add edges
        for (auto &edge : edges) {
            int u = edge[0]; // Source node of the edge.
            int v = edge[1]; // Destination node of the edge.
            int w = edge[2]; // Weight of the edge.
            dist[u][v] = w; // Update the distance matrix with the weight of the edge from u to v.
        }

        // Floyd-Warshall algorithm implementation
        // Iterate through all possible intermediate nodes (k).
        for (int k = 0; k < n; k++) {
            // Iterate through all possible source nodes (i).
            for (int i = 0; i < n; i++) {
                // Iterate through all possible destination nodes (j).
                for (int j = 0; j < n; j++) {
                    // Check if going from i to j through k is shorter than the current distance.
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }

        return dist; // Return the updated distance matrix containing the shortest path between all pairs of nodes.
    }
};

function aStar(grid: number[][], start: [number, number], goal: [number, number]): [number, number][] {
  // Get the number of rows in the grid
  const rows = grid.length
  // Get the number of columns in the grid
  const cols = grid[0].length

  // Define the heuristic function (Manhattan distance) to estimate the cost from a node to the goal
  const heuristic = (x: number, y: number) =>
    Math.abs(x - goal[0]) + Math.abs(y - goal[1])

  // Define possible movement directions (up, right, down, left)
  const dirs = [[0,1],[1,0],[0,-1],[-1,0]]

  // Initialize the open set with the starting node and its f-score (heuristic from start to goal)
  // The open set is a list of [f-score, x-coordinate, y-coordinate]
  const openSet: [number, number, number][] = [[heuristic(...start), start[0], start[1]]]

  // Initialize a map to store the node from which we reached a given node (for path reconstruction)
  const cameFrom = new Map<number, number>()
  // Initialize a map to store the cost from the start node to a given node
  const gScore = new Map<number, number>()
  // Initialize a set to store nodes that have already been evaluated
  const closedSet = new Set<number>()

  // Calculate a unique key for the starting node
  const startKey = start[0]*cols + start[1]
  // Set the g-score of the starting node to 0
  gScore.set(startKey, 0)

  // While there are nodes to evaluate in the open set
  while(openSet.length) {
    // Sort the open set by f-score (ascending order)
    openSet.sort((a,b)=>a[0]-b[0])
    // Get the node with the lowest f-score from the open set
    const [, x, y] = openSet.shift()!

    // Calculate the unique key for the current node
    const key = x*cols + y

    // If the current node has already been evaluated, skip it
    if(closedSet.has(key)) continue
    // Mark the current node as evaluated
    closedSet.add(key)

    // If the current node is the goal node, reconstruct and return the path
    if(x === goal[0] && y === goal[1]) {
      // Initialize the path with an empty array
      const path: [number,number][] = []
      // Start from the goal node
      let curr = key

      // Reconstruct the path by backtracking from the goal to the start
      while(curr !== startKey) {
        // Calculate the x and y coordinates of the current node
        const cx = Math.floor(curr/cols)
        const cy = curr%cols
        // Add the current node to the beginning of the path
        path.unshift([cx,cy])
        // Move to the parent node
        curr = cameFrom.get(curr)!
      }

      // Add the starting node to the beginning of the path
      path.unshift(start)
      // Return the reconstructed path
      return path
    }

    // For each neighbor of the current node
    for(const [dx,dy] of dirs) {
      // Calculate the coordinates of the neighbor node
      const nx = x+dx
      const ny = y+dy

      // If the neighbor node is out of bounds or is an obstacle, skip it
      if(nx<0 || ny<0 || nx>=rows || ny>=cols || grid[nx][ny]===1) continue

      // Calculate the unique key for the neighbor node
      const neighborKey = nx*cols+ny
      // Calculate the tentative g-score for the neighbor node
      const tentative = gScore.get(key)! + 1

      // If the neighbor node has not been visited yet, or if the tentative g-score is better than the current g-score
      if(!gScore.has(neighborKey) || tentative < gScore.get(neighborKey)!) {
        // Update the cameFrom map
        cameFrom.set(neighborKey, key)
        // Update the g-score
        gScore.set(neighborKey, tentative)

        // Calculate the f-score for the neighbor node
        const f = tentative + heuristic(nx,ny)
        // Add the neighbor node to the open set
        openSet.push([f,nx,ny])
      }
    }
  }

  // If no path is found, return an empty array
  return []
}

public static class Solution {

  // Used to maintain the order of insertion into the priority queue, in case of ties in fScore.
  int orderCounter = 0;

  public List<int[]> aStar(int[][] grid, int[] start, int[] goal) {

    // Get the number of rows and columns in the grid.
    int rows = grid.length, cols = grid[0].length;

    // Initialize a priority queue to store nodes to be explored.  Nodes with lower fScore are prioritized.
    PriorityQueue<Node> openSet =
      new PriorityQueue<>(
        (a, b) -> a.fScore != b.fScore
          ? a.fScore - b.fScore
          : a.order - b.order // If fScores are equal, prioritize by insertion order
      );

    // Initialize a map to store the cost (gScore) from the start node to each node.
    Map<Integer, Integer> gScore = new HashMap<>();
    // Initialize a map to store the parent of each node, which is used to reconstruct the path.
    Map<Integer, Integer> parent = new HashMap<>();

    // Initialize a 2D boolean array to keep track of visited nodes.
    boolean[][] closed = new boolean[rows][cols];

    // Calculate unique keys for the start and goal nodes.
    int startKey = start[0] * cols + start[1];
    int goalKey = goal[0] * cols + goal[1];

    // The cost from the start node to itself is 0.
    gScore.put(startKey, 0);

    // Add the start node to the open set with its initial fScore.
    openSet.add(
      new Node(
        start[0],
        start[1],
        heuristic(start, goal),
        orderCounter++
      )
    );

    // Define possible movement directions (up, right, down, left).
    int[][] directions = {{0,1},{1,0},{0,-1},{-1,0}};

    // While there are nodes to explore in the open set:
    while (!openSet.isEmpty()) {

      // Get the node with the lowest fScore from the open set.
      Node current = openSet.poll();

      // If the current node has already been visited, skip it.
      if (closed[current.row][current.col])
        continue;

      // Calculate the key for the current node.
      int currentKey = current.row * cols + current.col;

      // If the current node is the goal, reconstruct and return the path.
      if (currentKey == goalKey)
        return buildPath(parent, currentKey, cols);

      // Mark the current node as visited.
      closed[current.row][current.col] = true;

      // For each neighbor of the current node:
      for (int[] direction : directions) {

        // Calculate the row and column indices of the neighbor.
        int neighborRow = current.row + direction[0];
        int neighborCol = current.col + direction[1];

        // Check if the neighbor is within the grid bounds and is not an obstacle.
        if (
          neighborRow < 0 ||
          neighborCol < 0 ||
          neighborRow >= rows ||
          neighborCol >= cols ||
          grid[neighborRow][neighborCol] == 1
        ) continue;

        // Calculate the key for the neighbor.
        int neighborKey = neighborRow * cols + neighborCol;

        // Calculate the cost from the start node to the neighbor through the current node.
        int newGScore = gScore.get(currentKey) + 1;

        // If the neighbor has not been visited or the new gScore is lower than the previous gScore:
        if (
          !gScore.containsKey(neighborKey) ||
          newGScore < gScore.get(neighborKey)
        ) {

          // Update the gScore and parent of the neighbor.
          gScore.put(neighborKey, newGScore);
          parent.put(neighborKey, currentKey);

          // Calculate the fScore of the neighbor.
          int fScore =
            newGScore +
            Math.abs(neighborRow - goal[0]) +
            Math.abs(neighborCol - goal[1]);

          // Add the neighbor to the open set.
          openSet.add(
            new Node(
              neighborRow,
              neighborCol,
              fScore,
              orderCounter++
            )
          );
        }
      }
    }

    // If no path is found, return an empty list.
    return new ArrayList<>();
  }

  // Heuristic function (Manhattan distance) to estimate the cost from a node to the goal.
  int heuristic(int[] a, int[] b) {
    return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
  }

  // Reconstruct the path from the goal node to the start node using the parent map.
  List<int[]> buildPath(
    Map<Integer,Integer> parent,
    int currentKey,
    int cols
  ) {

    // Initialize the path list.
    List<int[]> path = new ArrayList<>();

    // Backtrack from the goal to the start.
    while (true) {
      path.add(0, new int[]{currentKey / cols, currentKey % cols});
      if (!parent.containsKey(currentKey)) break;
      currentKey = parent.get(currentKey);
    }

    // Return the reconstructed path.
    return path;
  }

  // Inner class representing a node in the grid.
  static class Node {

    int row;
    int col;
    int fScore;
    int order;

    Node(int row, int col, int fScore, int order) {
      this.row = row;
      this.col = col;
      this.fScore = fScore;
      this.order = order;
    }
  }
}

class Solution {
public:

  // Used to maintain the order of insertion into the priority queue in case of ties in fScore.
  int orderCounter = 0;

  // Structure to represent a node in the A* search.
  struct AStarNode {
    int row, col, fScore, order;
  };

  // Custom comparator for the priority queue.
  struct Compare {
    bool operator()(const AStarNode& a, const AStarNode& b) const {
      // If fScores are different, prioritize the smaller fScore.
      if (a.fScore != b.fScore) return a.fScore > b.fScore;
      // If fScores are equal, prioritize by insertion order.
      return a.order > b.order;
    }
  };

  // Function to find the shortest path using A* search algorithm.
  vector<vector<int>> aStar(
    vector<vector<int>>& grid,
    vector<int>& start,
    vector<int>& goal
  ) {

    // Get the number of rows and columns in the grid.
    int rows = grid.size(), cols = grid[0].size();

    // Initialize a priority queue to store nodes to be explored.  Nodes with lower fScore are prioritized.
    priority_queue<AStarNode, vector<AStarNode>, Compare> openSet;

    // Initialize an unordered map to store the cost (gScore) from the start node to each node.
    unordered_map<int,int> gScore;
    // Initialize an unordered map to store the parent of each node, which is used to reconstruct the path.
    unordered_map<int,int> parent;

    // Initialize a 2D boolean vector to keep track of visited nodes.
    vector<vector<bool>> closed(rows, vector<bool>(cols, false));

    // Calculate unique keys for the start and goal nodes.
    int startKey = start[0] * cols + start[1];
    int goalKey = goal[0] * cols + goal[1];

    // The cost from the start node to itself is 0.
    gScore[startKey] = 0;

    // Add the start node to the open set with its initial fScore.
    openSet.push({
      start[0],
      start[1],
      heuristic(start, goal),
      orderCounter++
    });

    // Define possible movement directions (up, right, down, left).
    int directions[4][2] = {{0,1},{1,0},{0,-1},{-1,0}};

    // While there are nodes to explore in the open set:
    while (!openSet.empty()) {

      // Get the node with the lowest fScore from the open set.
      AStarNode current = openSet.top();
      openSet.pop();

      // If the current node has already been visited, skip it.
      if (closed[current.row][current.col])
        continue;

      // Calculate the key for the current node.
      int currentKey = current.row * cols + current.col;

      // If the current node is the goal, reconstruct and return the path.
      if (currentKey == goalKey)
        return buildPath(parent, currentKey, cols);

      // Mark the current node as visited.
      closed[current.row][current.col] = true;

      // For each neighbor of the current node:
      for (auto& d : directions) {

        // Calculate the row and column indices of the neighbor.
        int nr = current.row + d[0];
        int nc = current.col + d[1];

        // Check if the neighbor is within the grid bounds and is not an obstacle.
        if (
          nr < 0 || nc < 0 ||
          nr >= rows || nc >= cols ||
          grid[nr][nc] == 1
        ) continue;

        // Calculate the key for the neighbor.
        int key = nr * cols + nc;

        // Calculate the cost from the start node to the neighbor through the current node.
        int newG = gScore[currentKey] + 1;

        // If the neighbor has not been visited or the new gScore is lower than the previous gScore:
        if (!gScore.count(key) || newG < gScore[key]) {

          // Update the gScore and parent of the neighbor.
          gScore[key] = newG;
          parent[key] = currentKey;

          // Calculate the fScore of the neighbor.
          int f =
            newG +
            abs(nr - goal[0]) +
            abs(nc - goal[1]);

          // Add the neighbor to the open set.
          openSet.push({
            nr,
            nc,
            f,
            orderCounter++
          });
        }
      }
    }

    // If no path is found, return an empty vector.
    return {};
  }

  // Heuristic function (Manhattan distance) to estimate the cost from a node to the goal.
  int heuristic(vector<int>& a, vector<int>& b) {
    return abs(a[0] - b[0]) + abs(a[1] - b[1]);
  }

  // Reconstruct the path from the goal node to the start node using the parent map.
  vector<vector<int>> buildPath(
    unordered_map<int,int>& parent,
    int key,
    int cols
  ) {

    // Initialize the path vector.
    vector<vector<int>> path;

    // Backtrack from the goal to the start.
    while (true) {

      // Insert the current node at the beginning of the path.
      path.insert(
        path.begin(),
        { key / cols, key % cols }
      );

      // If the current node is the start node, break the loop.
      if (!parent.count(key)) break;

      // Move to the parent node.
      key = parent[key];
    }

    // Return the reconstructed path.
    return path;
  }
};
